    // typeSet writes a canonical hash for an interface type set.
    void rec::typeSet(typeWriter* w, _TypeSet* s)
    {
        assert(w->ctxt != nullptr);
        auto first = true;
        for(auto [gocpp_ignored, m] : s->methods)
        {
            if(! first)
            {
                rec::byte(gocpp::recv(w), ';');
            }
            first = false;
            rec::string(gocpp::recv(w), m->object.name);
            rec::signature(gocpp::recv(w), gocpp::getValue<Signature*>(m->object.typ));
        }
        //Go switch emulation
        {
            int conditionId = -1;
            if(rec::isAll(gocpp::recv(s->terms))) { conditionId = 0; }
            else if(rec::isEmpty(gocpp::recv(s->terms))) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    break;
                // nothing to do
                case 1:
                    rec::string(gocpp::recv(w), rec::String(gocpp::recv(s->terms)));
                    break;
                default:
                    gocpp::slice<gocpp::string> termHashes = {};
                    for(auto [gocpp_ignored, term] : s->terms)
                    {
                        // terms are not canonically sorted, so we sort their hashes instead.
                        bytes::Buffer buf = {};
                        if(term->tilde)
                        {
                            rec::WriteByte(gocpp::recv(buf), '~');
                        }
                        rec::typ(gocpp::recv(newTypeHasher(& buf, w->ctxt)), term->typ);
                        termHashes = append(termHashes, rec::String(gocpp::recv(buf)));
                    }
                    sort::Strings(termHashes);
                    if(! first)
                    {
                        rec::byte(gocpp::recv(w), ';');
                    }
                    rec::string(gocpp::recv(w), mocklib::StringsJoin(termHashes, "|"_s));
                    break;
            }
        }
    }

    void rec::typeList(typeWriter* w, gocpp::slice<golang::types::Type> list)
    {
        rec::byte(gocpp::recv(w), '[');
        for(auto [i, typ] : list)
        {
            if(i > 0)
            {
                rec::byte(gocpp::recv(w), ',');
            }
            rec::typ(gocpp::recv(w), typ);
        }
        rec::byte(gocpp::recv(w), ']');
    }

    void rec::tParamList(typeWriter* w, gocpp::slice<TypeParam*> list)
    {
        rec::byte(gocpp::recv(w), '[');
        golang::types::Type prev = {};
        for(auto [i, tpar] : list)
        {
            // Determine the type parameter and its constraint.
            // list is expected to hold type parameter names,
            // but don't crash if that's not the case.
            if(tpar == nullptr)
            {
                rec::error(gocpp::recv(w), "nil type parameter"_s);
                continue;
            }
            if(i > 0)
            {
                if(tpar->bound != prev)
                {
                    // bound changed - write previous one before advancing
                    rec::byte(gocpp::recv(w), ' ');
                    rec::typ(gocpp::recv(w), prev);
                }
                rec::byte(gocpp::recv(w), ',');
            }
            prev = tpar->bound;
            rec::typ(gocpp::recv(w), tpar);
        }
        if(prev != nullptr)
        {
            rec::byte(gocpp::recv(w), ' ');
            rec::typ(gocpp::recv(w), prev);
        }
        rec::byte(gocpp::recv(w), ']');
    }

